def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [b for a, b in history]
    my = [a for a, b in history]

    opp_d_total = 0
    for x in opp:
        if x == 'D':
            opp_d_total += 1
    opp_c_total = n - opp_d_total

    my_d_total = 0
    for x in my:
        if x == 'D':
            my_d_total += 1

    last_opp = opp[-1]
    last_my = my[-1]

    def opp_streak(ch):
        s = 0
        for x in reversed(opp):
            if x == ch:
                s += 1
            else:
                break
        return s

    def my_streak(ch):
        s = 0
        for x in reversed(my):
            if x == ch:
                s += 1
            else:
                break
        return s

    opp_d_streak = opp_streak('D')
    my_d_streak = my_streak('D')

    if n < 3:
        return 'C'

    recent_len = 8 if n >= 8 else n
    recent_opp_d = 0
    for i in range(n - recent_len, n):
        if opp[i] == 'D':
            recent_opp_d += 1

    early_def = 0
    for i in range(min(4, n)):
        if opp[i] == 'D':
            early_def += 1

    remaining = 100 - n

    if remaining <= 0:
        return 'D'
    if remaining == 1:
        return 'D'
    if remaining == 2:
        return 'D'
    if remaining == 3:
        if opp_d_total > 0:
            return 'D'
        return 'D'
    if remaining == 4:
        if opp_c_total >= n - 2:
            return 'C'
        return 'D'
    if remaining == 5:
        if opp_d_total <= 1:
            return 'C'
        return 'D'

    if n < 6:
        if last_opp == 'D':
            return 'D'
        return 'C'

    if opp_d_total == 0:
        if last_my == 'D' and rng.random() < 0.75:
            return 'C'
        if n > 20 and n % 23 == 0:
            return 'D'
        return 'C'

    if early_def >= 4:
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    if opp_d_streak >= 5:
        if rng.random() < 0.04:
            return 'C'
        return 'D'

    if opp_d_streak >= 3:
        if last_my == 'D' and my_d_streak >= 2:
            if rng.random() < 0.20:
                return 'C'
            return 'D'
        return 'D'

    if opp_d_streak == 2:
        if last_my == 'D':
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        return 'D'

    if opp_d_streak == 1:
        if opp_d_total >= 3 and opp_d_total * 3 >= n:
            return 'D'
        if last_my == 'D':
            if rng.random() < 0.55:
                return 'C'
            return 'D'
        if rng.random() < 0.30:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if recent_opp_d >= 3:
            return 'D'
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    if recent_opp_d >= 4:
        return 'D'

    if opp_d_total >= 25 and opp_d_total * 2 >= n:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    if n >= 10:
        last10_d = 0
        start10 = n - 10
        for i in range(start10, n):
            if opp[i] == 'D':
                last10_d += 1
        if last10_d >= 3:
            if rng.random() < 0.10:
                return 'C'
            return 'D'

    if n >= 15:
        last15_d = 0
        start15 = n - 15
        for i in range(start15, n):
            if opp[i] == 'D':
                last15_d += 1
        if last15_d >= 4 and last15_d * 4 >= 15:
            if rng.random() < 0.15:
                return 'C'
            return 'D'

    if n >= 20:
        blocks = 0
        defects_in_blocks = 0
        i = 0
        while i < n:
            end = i + 5
            if end > n:
                end = n
            block_len = end - i
            d = 0
            for j in range(i, end):
                if opp[j] == 'D':
                    d += 1
            if d >= 2:
                defects_in_blocks += d
                blocks += 1
            i = end
        if blocks >= 3 and defects_in_blocks * 2 >= n:
            if rng.random() < 0.12:
                return 'C'
            return 'D'

    if last_my == 'D':
        if opp_c_total > opp_d_total:
            if rng.random() < 0.65:
                return 'C'
        return 'C' if rng.random() < 0.50 else 'D'

    if last_opp == 'C':
        if opp_d_total > 0 and opp_d_total * 4 >= n:
            if rng.random() < 0.12:
                return 'D'
        return 'C'

    return 'C'
